class BankAccount {
  private:
    long long balance;
  public:
    BankAccount(long long start) {
        balance = start;
    }
    void deposit(long long amount) {
        balance += amount;
    }
    void withdraw(long long amount) {
        if (amount <= balance) balance -= amount;
    }
    long long getBalance() {
        return balance;
    }
};

