    string line;
    getline(cin, line);

    // TODO: count vowels (a, e, i, o, u) case-insensitively and print the count

    return 0;
}

cpp.solution:
int main() {
    string line;
    getline(cin, line);
    int count = 0;
    for (char c : line) {
        char lower = tolower(c);
        if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u') {
            count++;
        }
    }
    cout << count << endl;
    return 0;
}
